create table public.academy_certificates (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), level smallint not null references public.academy_pathways(level), recipient_name text not null check(char_length(recipient_name) between 2 and 80), issued_at timestamptz not null default now(), revoked_at timestamptz, unique(user_id,level)); alter table public.academy_certificates enable row level security; revoke all on public.academy_certificates from public,anon,authenticated; grant select on public.academy_certificates to authenticated; grant select,insert on public.academy_certificates to service_role; create policy own_certificates on public.academy_certificates for select to authenticated using ((select auth.uid())=user_id);
